/bin/zsh -lc "set -e
pnpm build
node --input-type=module <<'EOF'
import fs from 'node:fs';
const pkg = JSON.parse(fs.readFileSync('package.json','utf8'));
const html = fs.readFileSync('index.html','utf8');
const app = fs.readFileSync('src/main.tsx','utf8');
const css = fs.readFileSync('src/styles.css','utf8');
const cityCount = (app.match(/\\{ id:'/g) || []).length;
const checks = {
  devPort9137: pkg.scripts.dev.includes('9137'),
  pnpmPinned: pkg.packageManager.startsWith('pnpm@'),
  modelTitle: html.includes('<title>GPT-5.6 Sol</title>'),
  modelHeading: app.includes('<h1>GPT-5.6 Sol</h1>'),
  catalogSize: cityCount,
  defaultCities: ['san-francisco','denpasar','geneva'].every(x => app.includes(x)),
  localStorage: app.includes(\"localStorage.setItem('orbit-time-state'\"),
  desktopLayout: app.includes('desktop-board'),
  mobileLayout: app.includes('mobile-board'),
  mobileBreakpoint: css.includes('@media(max-width:767px)'),
  overnightLogic: app.includes('value >= wake || value < sleep'),
  fractionalMinuteDisplay: app.includes(\"String(minute).padStart(2,'0')\"),
  buildArtifact: fs.existsSync('dist/index.html')
};
console.log(JSON.stringify(checks, null, 2));
if (Object.entries(checks).some(([k,v]) => k "'!== '"'catalogSize' && "'!v) || cityCount < 34) process.exit(1);
EOF
rg --files -g '"'"'!node_modules'"' -g '"'!dist'"' | sort
git status --short 2>/dev/null || true"

